"""Owner-only recovery page for browser data left at the retired shared origin."""
HTML = '''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Browser data recovery · Felo</title><style>body{max-width:760px;margin:50px auto;padding:24px;background:#090a16;color:#eeeaff;font:16px/1.7 system-ui}button{padding:12px 20px;background:#7044d7;color:white;border:0;border-radius:8px;cursor:pointer}pre{white-space:pre-wrap;overflow-wrap:anywhere}small{color:#c5bbdb}</style></head><body><h1>Recover older browser data</h1><p>Project previews now have separate addresses. Older browser-only records stay saved in this browser at this previous address. This page can download a copy for later import. It does not change or send your records.</p><button id="export">Download browser data copy</button><pre id="status" role="status">No data has been exported.</pre><small>Open this page on the computer and browser where you used the older project. Server records are separate and do not need this export.</small><script>
document.getElementById('export').onclick=()=>{try{const entries=[];for(let i=0;i<localStorage.length;i++){const key=localStorage.key(i);entries.push({key,value:localStorage.getItem(key)});}const data={format:'felo-browser-recovery-v1',origin:location.origin,exportedAt:new Date().toISOString(),entries};const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const link=document.createElement('a');link.href=url;link.download='felo-browser-data-'+new Date().toISOString().slice(0,10)+'.json';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);document.getElementById('status').textContent='Downloaded a copy of '+entries.length+' browser entries. Original values remain unchanged.';}catch(_){document.getElementById('status').textContent='This browser could not export its local storage. Nothing was changed.';}};
</script></body></html>'''
